function complete_parameter_values(parameters::AbstractVector)
    @assert length(parameters) == length(PARAMETER_NAMES)
    complete_parameters = Vector{eltype(parameters)}(undef, length(COMPLETE_PARAMETER_NAMES))
    complete_parameters[29] = parameters[29]
    complete_parameters[33] = parameters[33]
    complete_parameters[13] = parameters[13]
    complete_parameters[12] = parameters[12]
    complete_parameters[23] = parameters[23]
    complete_parameters[25] = parameters[25]
    complete_parameters[28] = parameters[28]
    complete_parameters[34] = parameters[34]
    complete_parameters[7] = parameters[7]
    complete_parameters[35] = parameters[35]
    complete_parameters[39] = parameters[39]
    complete_parameters[22] = parameters[22]
    complete_parameters[19] = parameters[19]
    complete_parameters[1] = parameters[1]
    complete_parameters[3] = parameters[3]
    complete_parameters[10] = parameters[10]
    complete_parameters[26] = parameters[26]
    complete_parameters[16] = parameters[16]
    complete_parameters[37] = parameters[37]
    complete_parameters[9] = parameters[9]
    complete_parameters[5] = parameters[5]
    complete_parameters[32] = parameters[32]
    complete_parameters[36] = parameters[36]
    complete_parameters[6] = parameters[6]
    complete_parameters[8] = parameters[8]
    complete_parameters[38] = parameters[38]
    complete_parameters[11] = parameters[11]
    complete_parameters[27] = parameters[27]
    complete_parameters[2] = parameters[2]
    complete_parameters[30] = parameters[30]
    complete_parameters[31] = parameters[31]
    complete_parameters[17] = parameters[17]
    complete_parameters[14] = parameters[14]
    complete_parameters[15] = parameters[15]
    complete_parameters[18] = parameters[18]
    complete_parameters[20] = parameters[20]
    complete_parameters[4] = parameters[4]
    complete_parameters[21] = parameters[21]
    complete_parameters[24] = parameters[24]
    complete_parameters[51] = (complete_parameters[8] * (1 - complete_parameters[38])) / (1 - complete_parameters[38] / complete_parameters[14])
    complete_parameters[48] = complete_parameters[7] / (1 - complete_parameters[2])
    complete_parameters[47] = (1 - complete_parameters[3] / complete_parameters[2]) / (1 - (complete_parameters[3] * complete_parameters[38]) / complete_parameters[14])
    complete_parameters[42] = 1 / complete_parameters[2]
    complete_parameters[43] = complete_parameters[42] - (1 - complete_parameters[11])
    complete_parameters[44] = complete_parameters[23]
    complete_parameters[45] = complete_parameters[24]
    complete_parameters[46] = complete_parameters[24]
    complete_parameters[50] = complete_parameters[9] / (complete_parameters[44] * complete_parameters[43])
    complete_parameters[49] = complete_parameters[7] / ((1 - complete_parameters[3]) - complete_parameters[47] * complete_parameters[8] * (1 - complete_parameters[38]))
    complete_parameters[52] = (((1 - complete_parameters[9]) * complete_parameters[16]) / (1 + (1 / complete_parameters[2] - 1) * complete_parameters[51] * complete_parameters[49])) * (1 / complete_parameters[44])
    complete_parameters[53] = (1 - complete_parameters[52]) - complete_parameters[11] * complete_parameters[50]
    complete_parameters[54] = (((1 - complete_parameters[16]) * (1 - complete_parameters[9])) / (complete_parameters[44] * complete_parameters[45] * complete_parameters[53])) ^ (1 / (1 + complete_parameters[6]))
    complete_parameters[55] = ((complete_parameters[16] * (1 - complete_parameters[9])) / (complete_parameters[44] * complete_parameters[46] * complete_parameters[52])) ^ (1 / (1 + complete_parameters[6]))
    complete_parameters[41] = complete_parameters[50] ^ (complete_parameters[9] / (1 - complete_parameters[9])) * complete_parameters[54] ^ (1 - complete_parameters[16]) * complete_parameters[55] ^ complete_parameters[16]
    complete_parameters[56] = complete_parameters[41] - complete_parameters[11] * complete_parameters[50] * complete_parameters[41]
    complete_parameters[40] = complete_parameters[50] * complete_parameters[11] * complete_parameters[41]
    complete_parameters[57] = complete_parameters[50] * complete_parameters[41]
    complete_parameters[58] = complete_parameters[48] * complete_parameters[53] * complete_parameters[41] + complete_parameters[49] * complete_parameters[52] * complete_parameters[41]
    return complete_parameters
end

function residuals_original(parameters::AbstractVector, solution::AbstractVector)
    @assert length(parameters) == length(PARAMETER_NAMES)
    @assert length(solution) == length(ORIGINAL_SOLUTION_NAMES)
    complete_parameters = complete_parameter_values(parameters)
    return [
        (solution[9] + solution[10] + solution[15]) - solution[35],
        solution[26] - ((complete_parameters[2] * solution[23]) / solution[11]) * solution[26],
        (solution[26] * solution[30]) / solution[33] - solution[6] * solution[19] ^ complete_parameters[6],
        solution[26] * solution[21] - (solution[28] + solution[26] * complete_parameters[2] * solution[21]),
        (solution[10] + solution[21] * (solution[14] - solution[14]) + (solution[23] * solution[7]) / solution[11]) - (solution[31] * solution[20] + solution[7] + complete_parameters[15] * log(solution[3])),
        solution[27] * (1 - solution[17]) - complete_parameters[3] * (solution[23] / solution[11] - (complete_parameters[38] * solution[17]) / solution[11]) * solution[27],
